head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.selfID = ""; // ID를 opener가 넘기는 값을 받는 변수형태로 사용하기 위함.
scwin.vScrenID = 'ULDSTF30002.xml';
scwin.strTeam = js_team;
scwin.strDepCd = js_dep_cd.substring(0, 2);
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.resizeToWin = function() {
    frame.Width = 280;
    frame.Height = 420;
    $c.stf.MoveCenterOfParent();
};


//카테고리(선택박스)
scwin.fn_SetCode = function() {
    var flag = (js_market == "1") ? "0" : "9";
    var url = "/DisclosureSchedule.do?method=listAdmItmCmb&For=C";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=" + flag;
    url += "&MKT_ID=" + js_market;
    url += "&TEAM_ID=" + js_team;
    dts_Adm_Itm_Cmb.DataID = encodeURI(url);
    dts_Adm_Itm_Cmb.Reset();
    //alert(url);
    if (js_market == "2" || js_market == "9" || js_market == "6") {
        // 코넥스 추가 20130522 LDJ
        cmb_Adm_Itm.setDisabled(false);
    }
    //cmb_Adm_Itm.Enable2 = true;
    $c.stf.setObjectValue(cmb_Adm_Itm, "9");
    //alert(getObjectValue(cmb_Adm_Itm));

};
scwin.fn_HideGridCol = function(GridID) {
    var ColCnt = GridID.getTotalCol();
    for (var i = 0; i < ColCnt; i++) {
        var ColID = GridID.GetColumnID(i);
        var HeaderNm = GridID.GetHdrDispName(-3, ColID);
        if (scwin.fn_IsEngChar(HeaderNm)) {
            // 영문 컬럼이면 숨겨라.
            GridID.setColumnProp(ColID, "Show", false);
        }
    }
};
scwin.fn_HideDebugCtrls = function() {
    scwin.fn_HideGridCol(grd_Adm_Itm);
};


//카테고리에 따른 목록
scwin.listManageItem = function() {
    //증권상품팀 구분을 위해 20210528
    var flag = "0";
    if (js_market == "1") {
        if (scwin.strDepCd == "2B") {
            flag = "6";
            scwin.strTeam = "16";
        }
        if (js_dep_cd == "11D0") {
            flag = "3";
            scwin.strTeam = "11D0";
        }
    } else {
        flag = $c.stf.getObjectValue(cmb_Adm_Itm);
    }

    //var flag = (js_market == "1") ? "0":  getObjectValue(cmb_Adm_Itm);
    var url = "/DisclosureSchedule.do?method=listManageItem";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=" + flag;
    url += "&TEAM_ID=" + scwin.strTeam;
    url += "&MKT_ID=" + js_market;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Adm_Itm_List.DataID = encodeURI(url);
    dts_Adm_Itm_List.Reset();
};
scwin.fn_IsEngChar = function(str) {
    var re = /[^-a-z_A-Z]/; // 영문자가 아닌 게 있는 걸 찾아라.
    return !re.test(str);
};
scwin.setAdm_Itm = function(GridID, row, ColID) {
    if (scwin.selfID == "ONLYFORGRID") {
        scwin.setAdm_Itm_For_Grid(GridID, row, ColID);
    } else {
        scwin.setAdm_Itm_Default(GridID, row, ColID);
    }
};
scwin.setAdm_Itm_Default = async function(GridID, row, ColID) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var parentWin = $c.frame.path("../");
    $c.stf.setObjectValue(parentWin.txb_SCHDL_ADM_ITM_TP_CD, objDataID.getCellData(row, "SCHDL_ADM_ITM_TP_CD"));
    $c.stf.setObjectValue(parentWin.txb_SCHDL_ADM_ITM_TP_NM, objDataID.getCellData(row, "CD_NM"));
    //setObjectValue(parentWin.txb_DISCLS_SCHDL_ADM_CONTN, objDataID.NameString(row, "CD_NM"));

    await $c.frame.CloseFrame();
};
scwin.setAdm_Itm_For_Grid = async function(GridID, row, ColID) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var parentWin = $c.frame.path("../");
    //var parentDataID = opener.document.all();
    parentWin.dts_Grid.setCellData(parentWin.dts_Grid.getFocusedRowIndex(), "SCHDL_ADM_ITM_TP_CD", objDataID.getCellData(row, "SCHDL_ADM_ITM_TP_CD"));
    parentWin.dts_Grid.setCellData(parentWin.dts_Grid.getFocusedRowIndex(), "SCHDL_ADM_ITM_TP_NM", objDataID.getCellData(row, "CD_NM"));
    //parentWin.dts_Grid.NameValue(parentWin.dts_Grid.RowPosition, "DISCLS_SCHDL_ADM_CONTN") = objDataID.NameString(row, "CD_NM");

    await $c.frame.CloseFrame();
};
scwin.cmb_Adm_Itm_OnSelChange = function() {
    scwin.listManageItem();
};
scwin.grd_Adm_Itm_OnDblClick = function(row, colid) {
    scwin.setAdm_Itm(grd_Adm_Itm, row, colid);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Adm_Itm_Cmb_OnLoadCompleted = function(rowcount) {
    //alert('dts_Adm_Itm_Cmb.OnLoadCompleted('+rowcount+')');

};
scwin.dts_Adm_Itm_Cmb_OnLoadError = function() {
    $c.stf.alert_error(dts_Adm_Itm_Cmb);
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    scwin.resizeToWin();
    scwin.fn_SetCode();
    scwin.selfID = frame.FrameID; // ID 할당.

};
